"use client";

// Wind Type by Louis Studios.
// 200 more hand-made React components at https://studios.lou15.com/?ref=21st-code

import * as React from "react";

export interface WindTypeProps {
  /** The word to set. Short display words (one to eight characters) read best; the text auto-fits the container. */
  text?: string;
  /** Ink colour of the letters away from the wind band: the deep navy at the top and bottom of each letter. */
  color?: string;
  /** Ink colour the letters warm up to as they approach the wind band. */
  accent?: string;
  /** Colour of the light along the seam where the dragged strokes meet, and of the needle tips. */
  glow?: string;
  /** Sky colour at the top left of the backdrop. Pass "transparent" to draw the letters only. */
  background?: string;
  /** Pale haze colour the sky fades to at the bottom right. */
  haze?: string;
  /** Leave unset to use the built-in display alphabet (A to Z, 0 to 9, cut so every letter drags into clean needles). Pass a CSS font stack to set the word in a system or self-hosted font instead; nothing is downloaded. */
  font?: string;
  /** Font weight for a custom `font`, in steps of 100. The built-in alphabet has one weight. */
  weight?: number;
  /** Extra letter spacing in em, added to the alphabet's own spacing. Negative tightens. */
  tracking?: number;
  /** Height of the wind band's seam above the baseline, as a fraction of the cap height (0 is the baseline, 1 the cap line). */
  bandPosition?: number;
  /** Vertical reach of the bend above and below the seam, as a fraction of the cap height. Larger values bend more of each letter. */
  bandHeight?: number;
  /** How far each stroke is dragged at the seam, as a fraction of the cap height. This is the length of the resting needles. */
  streakLength?: number;
  /** Multiplier on the automatic needle reach. Short words keep the full reach; on longer words each needle is cut back so it ends around the gap before the next stroke instead of running across it. 1 keeps the automatic length, values above 1 lengthen the needles, values below 1 shorten them. */
  reach?: number;
  /** Strength of the gusts, 0 to 2. At 0 the word holds its resting smear and only the band drifts. */
  windStrength?: number;
  /** Speed multiplier for the gust loop. One loop lasts 10 seconds at 1. */
  speed?: number;
  /** Which way the wind drags the ink. */
  direction?: "right" | "left";
  /** Let the pointer act as a gust: moving across the word drags the band in the pointer's direction. */
  interactive?: boolean;
  /** Freeze the animation. */
  paused?: boolean;
  /** Render this moment of the loop, in seconds, instead of running the clock. For stills and tests. */
  time?: number;
  /** Extra class on the outer element. */
  className?: string;
  /** Extra style on the outer element. */
  style?: React.CSSProperties;
}

type RGB = [number, number, number];

const LOOP = 10; // seconds per gust loop at speed 1
const SUB = 8; // sub-rows per device pixel inside the wind band
const NEED = 0.41; // share of the drag that stretches the leading edge into a needle

/* Parse any CSS colour into 0..1 rgb plus alpha, through a 1x1 canvas so hex, rgb(), hsl() and names all work. */
let parseCtx: CanvasRenderingContext2D | null = null;
function parseColor(c: string, fallback: RGB): { rgb: RGB; a: number } {
  if (typeof document === "undefined") return { rgb: fallback, a: 1 };
  if (!parseCtx) {
    const cv = document.createElement("canvas");
    cv.width = 1;
    cv.height = 1;
    parseCtx = cv.getContext("2d", { willReadFrequently: true });
  }
  const g = parseCtx;
  if (!g) return { rgb: fallback, a: 1 };
  g.clearRect(0, 0, 1, 1);
  g.fillStyle = "#000000"; // ls:keep
  g.fillStyle = c;
  g.fillRect(0, 0, 1, 1);
  const d = g.getImageData(0, 0, 1, 1).data;
  const a = d[3] / 255;
  if (a <= 0) return { rgb: fallback, a: 0 };
  return { rgb: [d[0] / 255 / a, d[1] / 255 / a, d[2] / 255 / a], a };
}

/* The built-in display alphabet, cut for the effect. Font units: baseline 0, cap line 1000, y up.
   Stems are 155 wide; every horizontal bar, bowl join and crossing sits clear of the default wind band
   (seam at 388, bend reach about 270 to 520), so each letter crosses the seam only with vertical or
   diagonal strokes and drags into clean needles with sky between them.
   Shapes: [0, x0, y0, x1, y1] box, [1, ...xy] polygon, [2, cx, cy, rx, ry, tx, ty, a0, a1] superelliptic arc
   band (degrees, counterclockwise), [3, cx, cy, rx, ry, tx, ty] ring, [4, x0, y0, x1, y1, w] stroke with
   level ends and horizontal width w. */
type Glyph = [number, number, number, number[][]]; // ink width, left side bearing, right side bearing, shapes
const QS = 160; // round stem
const GLYPHS: Record<string, Glyph> = {
  A: [896, 18, 22, [[1, 0, 0, 163, 0, 447, 843, 736, 0, 896, 0, 532, 1000, 362, 1000]]],
  B: [780, 70, 45, [[0, 0, 0, 155, 1000], [0, 0, 870, 400, 1000], [0, 0, 550, 420, 680], [0, 0, 0, 390, 130], [2, 400, 775, 300, 225, QS, 130, -90, 90], [2, 390, 340, 390, 340, QS + 5, 130, -90, 90]]],
  C: [820, 45, 35, [[2, 410, 500, 410, 512, QS, 130, 42, 318]]],
  D: [810, 70, 45, [[0, 0, 0, 155, 1000], [0, 0, 870, 330, 1000], [0, 0, 0, 330, 130], [2, 330, 500, 480, 500, QS, 130, -90, 90]]],
  E: [690, 70, 30, [[0, 0, 0, 155, 1000], [0, 0, 870, 680, 1000], [0, 0, 550, 620, 680], [0, 0, 0, 690, 130]]],
  F: [670, 70, 20, [[0, 0, 0, 155, 1000], [0, 0, 870, 670, 1000], [0, 0, 550, 610, 680]]],
  G: [840, 45, 65, [[2, 420, 500, 420, 512, QS, 130, 42, 350], [0, 680, 300, 840, 680], [0, 440, 550, 840, 680]]],
  H: [850, 70, 70, [[0, 0, 0, 155, 1000], [0, 695, 0, 850, 1000], [0, 0, 550, 850, 680]]],
  I: [155, 70, 70, [[0, 0, 0, 155, 1000]]],
  J: [640, 25, 70, [[0, 485, 330, 640, 1000], [2, 320, 340, 320, 352, 155, 130, 205, 360]]],
  K: [800, 70, 15, [[0, 0, 0, 155, 1000], [4, 230, 560, 700, 1000, 200], [4, 330, 640, 700, 0, 195]]],
  L: [640, 70, 15, [[0, 0, 0, 155, 1000], [0, 0, 0, 640, 130]]],
  M: [960, 70, 70, [[0, 0, 0, 155, 1000], [0, 805, 0, 960, 1000], [4, 85, 1000, 480, 0, 172], [4, 875, 1000, 480, 0, 172]]],
  N: [840, 70, 70, [[0, 0, 0, 155, 1000], [0, 685, 0, 840, 1000], [4, 110, 1000, 730, 0, 182]]],
  O: [880, 45, 45, [[3, 440, 500, 440, 512, QS, 130]]],
  P: [760, 70, 30, [[0, 0, 0, 155, 1000], [0, 0, 870, 360, 1000], [0, 0, 550, 360, 680], [2, 360, 775, 400, 225, QS, 130, -90, 90]]],
  Q: [880, 45, 45, [[3, 440, 500, 440, 512, QS, 130], [4, 575, 215, 800, -70, 175]]],
  R: [754, 70, 20, [[0, 0, 0, 155, 1000], [1, 60, 1000, 400, 1000, 443, 998, 514, 984, 552, 971, 578, 957, 599, 944, 617, 930, 633, 917, 646, 903, 659, 890, 669, 876, 679, 863, 687, 850, 693, 836, 701, 823, 706, 809, 711, 796, 715, 782, 719, 769, 721, 755, 724, 742, 725, 728, 726, 715, 726, 701, 726, 688, 725, 674, 724, 661, 722, 647, 719, 634, 716, 620, 712, 607, 707, 594, 703, 580, 697, 567, 691, 553, 683, 540, 676, 526, 673, 519, 659, 490, 645, 462, 632, 433, 622, 405, 613, 376, 607, 348, 605, 320, 608, 291, 615, 262, 627, 234, 754, 0, 576, 0, 453, 234, 441, 262, 434, 291, 432, 319, 434, 348, 440, 376, 448, 405, 459, 434, 471, 462, 485, 490, 499, 519, 501, 526, 507, 540, 515, 553, 524, 567, 534, 580, 541, 594, 548, 607, 554, 620, 558, 634, 561, 647, 564, 661, 566, 674, 567, 688, 567, 701, 566, 715, 565, 728, 562, 742, 558, 755, 553, 769, 547, 782, 539, 796, 530, 809, 517, 823, 502, 836, 492, 843, 480, 850, 465, 856, 434, 863, 351, 870, 100, 870]]],
  S: [760, 40, 40, [[2, 380, 784, 350, 228, QS - 8, 130, 25, 270], [2, 380, 337, 380, 349, QS, 130, -160, 90]]],
  T: [780, 15, 15, [[0, 0, 870, 780, 1000], [0, 312, 0, 467, 1000]]],
  U: [820, 70, 70, [[0, 0, 330, 155, 1000], [0, 665, 330, 820, 1000], [2, 410, 340, 410, 352, 155, 130, 180, 360]]],
  V: [980, 18, 18, [[4, 95, 1000, 490, 0, 188], [4, 885, 1000, 490, 0, 188]]],
  W: [1380, 18, 18, [[4, 85, 1000, 375, 0, 165], [4, 690, 1000, 375, 0, 165], [4, 690, 1000, 1005, 0, 165], [4, 1295, 1000, 1005, 0, 165]]],
  X: [900, 18, 18, [[4, 100, 1000, 450, 690, 188], [4, 800, 1000, 450, 690, 188], [4, 450, 690, 110, 0, 188], [4, 450, 690, 790, 0, 188]]],
  Y: [900, 18, 18, [[4, 100, 1000, 450, 610, 188], [4, 800, 1000, 450, 610, 188], [0, 372, 0, 528, 640]]],
  Z: [760, 35, 35, [[0, 0, 870, 760, 1000], [0, 0, 0, 760, 130], [4, 655, 880, 105, 120, 205]]],
  "0": [760, 45, 45, [[3, 380, 500, 380, 512, QS, 130]]],
  "1": [420, 30, 70, [[0, 265, 0, 420, 1000], [1, 265, 1000, 420, 1000, 265, 845, 30, 700, 30, 845]]],
  "2": [760, 40, 40, [[2, 380, 700, 360, 312, QS, 130, -15, 160], [4, 650, 620, 95, 130, 215], [0, 0, 0, 760, 130]]],
  "3": [740, 35, 45, [[2, 370, 775, 330, 225, QS - 8, 130, -90, 150], [2, 370, 334, 370, 346, QS, 130, -150, 90], [0, 240, 550, 380, 680]]],
  "4": [800, 25, 40, [[0, 540, 0, 695, 1000], [0, 0, 110, 800, 240], [4, 610, 1000, 100, 240, 200]]],
  "5": [740, 45, 40, [[0, 140, 870, 720, 1000], [0, 140, 560, 295, 1000], [2, 370, 334, 370, 346, QS, 130, -155, 126]]],
  "6": [760, 45, 40, [[3, 380, 334, 380, 346, QS, 130], [2, 380, 500, 380, 512, QS, 130, 52, 200]]],
  "7": [740, 25, 25, [[0, 0, 870, 740, 1000], [4, 640, 890, 215, 0, 200]]],
  "8": [760, 40, 40, [[3, 380, 781, 340, 231, QS - 8, 130], [3, 380, 334, 380, 346, QS, 130]]],
  "9": [760, 40, 45, [[3, 380, 775, 380, 237, QS, 130], [2, 380, 500, 380, 512, QS, 130, -128, 28]]],
  ".": [170, 60, 60, [[0, 0, 0, 170, 170]]],
  ",": [170, 60, 60, [[0, 0, 0, 170, 170], [1, 60, 20, 170, 20, 90, -170, 10, -170]]],
  "-": [420, 50, 50, [[0, 0, 560, 420, 690]]],
  "!": [170, 65, 65, [[0, 8, 320, 162, 1000], [0, 0, 0, 170, 170]]],
  ":": [170, 65, 65, [[0, 0, 0, 170, 170], [0, 0, 560, 170, 730]]],
  "'": [155, 60, 60, [[0, 0, 700, 155, 1000]]],
};
const SPACE = 300;
const KERN: Record<string, number> = {
  AV: -60, VA: -60, AW: -45, WA: -45, AY: -70, YA: -70, AT: -55, TA: -55, LT: -80, LV: -70, LY: -80, LW: -45,
  FA: -55, PA: -45, TO: -15, OT: -15, VO: -15, OV: -15, YO: -20, OY: -20, KO: -20, LO: -10,
};
const SYSTEM_FONT = 'system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif';

const glyphCache = new Map<string, Path2D>();
function superPt(cx: number, cy: number, rx: number, ry: number, deg: number, out: number[]) {
  const t = (deg * Math.PI) / 180;
  const c = Math.cos(t);
  const s = Math.sin(t);
  out.push(cx + rx * Math.sign(c) * Math.pow(Math.abs(c), 0.8), cy + ry * Math.sign(s) * Math.pow(Math.abs(s), 0.8));
}
function arcPts(cx: number, cy: number, rx: number, ry: number, a0: number, a1: number, out: number[]) {
  const n = Math.max(8, Math.ceil(Math.abs(a1 - a0) / 1.5));
  for (let i = 0; i <= n; i++) superPt(cx, cy, rx, ry, a0 + ((a1 - a0) * i) / n, out);
}
/* Adds one closed polygon, turned so ink runs counterclockwise and holes clockwise. Every piece of a glyph
   goes into one path filled nonzero, so pieces that butt together join as one shape with no anti-aliased seam. */
function polyPath(p: Path2D, pts: number[], hole = false) {
  let area = 0;
  const n = pts.length / 2;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    area += pts[i * 2] * pts[j * 2 + 1] - pts[j * 2] * pts[i * 2 + 1];
  }
  const flip = hole ? area > 0 : area < 0;
  for (let s = 0; s < n; s++) {
    const i = flip ? n - 1 - s : s;
    if (s === 0) p.moveTo(pts[i * 2], pts[i * 2 + 1]);
    else p.lineTo(pts[i * 2], pts[i * 2 + 1]);
  }
  p.closePath();
}
function glyphPath(ch: string) {
  let p = glyphCache.get(ch);
  if (p) return p;
  p = new Path2D();
  for (const sh of GLYPHS[ch][3]) {
    const k = sh[0];
    if (k === 0) polyPath(p, [sh[1], sh[2], sh[3], sh[2], sh[3], sh[4], sh[1], sh[4]]);
    else if (k === 1) polyPath(p, sh.slice(1));
    else if (k === 2 || k === 3) {
      const [, cx, cy, rx, ry, tx, ty] = sh;
      const a0 = k === 2 ? sh[7] : 0;
      const a1 = k === 2 ? sh[8] : 360;
      const o: number[] = [];
      const i: number[] = [];
      arcPts(cx, cy, rx, ry, a0, a1, o);
      arcPts(cx, cy, rx - tx, ry - ty, a1, a0, i);
      if (k === 2) polyPath(p, o.concat(i));
      else {
        polyPath(p, o);
        polyPath(p, i, true);
      }
    } else {
      const [, x0, y0, x1, y1, w] = sh;
      polyPath(p, [x0 - w / 2, y0, x0 + w / 2, y0, x1 + w / 2, y1, x1 - w / 2, y1]);
    }
  }
  glyphCache.set(ch, p);
  return p;
}

interface Item {
  ch: string;
  x: number; // glyph origin, css px
  b: boolean; // drawn from the built-in alphabet
}

interface Layout {
  cssW: number;
  cssH: number;
  dpr: number;
  cap: number; // cap height, css px
  unit: number; // css px per font unit of the built-in alphabet
  fs: number; // font size for system-font glyphs, css px
  fontCss: string;
  weight: number;
  items: Item[];
  baseline: number; // css px
  inkL: number;
  inkR: number;
  needles: Needle[]; // strokes crossing the seam, in cap-100 units from inkL, with their reach factor
  rest: number; // reach factor outside the word, and everywhere when the seam row could not be read
}

/* One stroke where it crosses the seam: its left and right edge (cap height = 100, measured from the left ink edge)
   and the factor its drag and needle are scaled by. */
interface Needle {
  l: number;
  r: number;
  k: number;
  g: number; // most a gust or the pointer may grow this needle's reach, as a multiple of its resting reach
}

/* A needle value at a position along the word: flat across each stroke, eased with a smoothstep through the gap
   to the next stroke, so the drag field stays one smooth function of x. */
function needleAt(N: Needle[], u: number, key: "k" | "g", rest: number) {
  if (!N.length) return rest;
  if (u <= N[0].r) return N[0][key];
  for (let i = 0; i < N.length - 1; i++) {
    const a = N[i];
    const b = N[i + 1];
    if (u <= a.r) return a[key];
    if (u < b.l) {
      const t = (u - a.r) / Math.max(b.l - a.r, 1e-3);
      return a[key] + (b[key] - a[key]) * t * t * (3 - 2 * t);
    }
  }
  return N[N.length - 1][key];
}
const FREE = 1e3; // no limit on gust growth

function fontString(weight: number, size: number, font: string) {
  return `${Math.round(weight)} ${size}px ${font}`;
}

function drawWord(g: CanvasRenderingContext2D, L: Layout) {
  g.textBaseline = "alphabetic";
  g.textAlign = "left";
  g.font = fontString(L.weight, L.fs, L.fontCss);
  for (const it of L.items) {
    if (it.b) {
      g.save();
      g.translate(it.x, L.baseline);
      g.scale(L.unit, -L.unit);
      g.fill(glyphPath(it.ch), "nonzero");
      g.restore();
    } else g.fillText(it.ch, it.x, L.baseline);
  }
}

function layoutWord(
  g: CanvasRenderingContext2D,
  text: string,
  font: string | undefined,
  weight: number,
  tracking: number,
  look: { s: number; e: number; band: number; wind: number; reach: number },
  dir: number,
  cssW: number,
  cssH: number,
  dpr: number,
): Layout {
  const builtin = !font;
  const fontCss = font || SYSTEM_FONT;
  const chars = Array.from(builtin ? text.toUpperCase() : text);
  // Everything is measured at a cap height of 100 px, then scaled.
  g.font = fontString(weight, 100, fontCss);
  const capF = g.measureText("H").actualBoundingBoxAscent || 70;
  const fs100 = (100 * 100) / capF;
  g.font = fontString(weight, fs100, fontCss);
  const u = 0.1;
  const em = 100 / 0.72;
  const xs: number[] = [];
  const bs: boolean[] = [];
  let inkL = Infinity;
  let inkR = -Infinity;
  let asc = 100;
  let desc = 0;
  let pen = 0;
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    const gl = builtin ? GLYPHS[ch] : undefined;
    if (builtin) {
      if (i > 0) pen += (KERN[chars[i - 1] + ch] || 0) * u + tracking * em;
      if (gl) {
        xs.push(pen + gl[1] * u); // glyph shapes start at their left ink edge
        bs.push(true);
        inkL = Math.min(inkL, pen + gl[1] * u);
        inkR = Math.max(inkR, pen + (gl[1] + gl[0]) * u);
        asc = Math.max(asc, 101.2);
        desc = Math.max(desc, ch === "Q" || ch === "," ? 17 : 1.2);
        pen += (gl[0] + gl[1] + gl[2]) * u;
        continue;
      }
      xs.push(pen);
      bs.push(false);
      const m = g.measureText(ch);
      if (ch.trim()) {
        inkL = Math.min(inkL, pen - m.actualBoundingBoxLeft);
        inkR = Math.max(inkR, pen + m.actualBoundingBoxRight);
        asc = Math.max(asc, m.actualBoundingBoxAscent);
        desc = Math.max(desc, m.actualBoundingBoxDescent);
      }
      pen += ch === " " ? SPACE * u : m.width;
    } else {
      const x = g.measureText(chars.slice(0, i).join("")).width + i * tracking * em;
      xs.push(x);
      bs.push(false);
      const m = g.measureText(ch);
      if (ch.trim()) {
        inkL = Math.min(inkL, x - m.actualBoundingBoxLeft);
        inkR = Math.max(inkR, x + m.actualBoundingBoxRight);
      }
      asc = Math.max(asc, m.actualBoundingBoxAscent);
      desc = Math.max(desc, m.actualBoundingBoxDescent);
    }
  }
  if (!isFinite(inkL)) {
    inkL = 0;
    inkR = 1;
  }
  let needles: Needle[] = [];
  const make = (cap: number, shift: number, baseline: number): Layout => {
    const s = cap / 100;
    return {
      cssW,
      cssH,
      dpr,
      cap,
      unit: (cap / 100) * u,
      fs: fs100 * s,
      fontCss,
      weight,
      items: chars.map((ch, i) => ({ ch, x: xs[i] * s + shift, b: bs[i] })),
      baseline,
      inkL: inkL * s + shift,
      inkR: inkR * s + shift,
      needles,
      rest: look.reach,
    };
  };
  // How far the resting needles reach past the ink: read the ink runs on the seam row at this 100 px size.
  let over = 0;
  if (typeof document !== "undefined" && inkR > inkL + 1) {
    const w = Math.ceil(inkR - inkL + 8);
    const cv = document.createElement("canvas");
    cv.width = w;
    cv.height = 1;
    const mg = cv.getContext("2d", { willReadFrequently: true });
    if (mg) {
      mg.fillStyle = "#ffffff"; // ls:keep
      drawWord(mg, make(100, 4 - inkL, 0.5 + look.band * 100)); // puts the seam on the canvas's single row
      const d = mg.getImageData(0, 0, w, 1).data;
      const runs: [number, number][] = [];
      let open = -1;
      for (let x = 0; x <= w; x++) {
        const on = x < w && d[x * 4 + 3] >= 128;
        if (on && open < 0) open = x;
        if (!on && open >= 0) {
          runs.push([open - 4, x - 4]); // from the left ink edge
          open = -1;
        }
      }
      // Needle reach adapts to the word, measured on the real seam row, in cap heights:
      // - the whole word's reach eases from 1 at an ink width of 2.2 caps (AIR) down to 0.6 at 7.5 caps and wider;
      // - each needle is then cut back so its resting tip lands on the next stroke downwind instead of running across
      //   it (never below 0.45 of its length); this fit fades in between 2.2 and 5.2 caps.
      // Words up to about 2.2 caps wide keep exactly the pin's reach, and every step is smooth in the word's width.
      const wid = inkR - inkL;
      const ease = (a: number, b: number) => {
        const t = Math.min(1, Math.max(0, (wid / 100 - a) / (b - a)));
        return t * t * (3 - 2 * t);
      };
      const word = 1 - 0.4 * ease(2.2, 7.5);
      const fade = ease(2.2, 5.2);
      needles = runs.map(([l, r], i) => {
        const xn = Math.min(1, Math.max(0, (l + r) / 2 / wid));
        const full = (look.s * 100 * lensAt(xn, dir) + look.e * 100) * word;
        const nb = runs[i + dir];
        const gap = nb ? (dir > 0 ? nb[0] - r : l - nb[1]) : Infinity;
        const fit = Math.min(1, Math.max(0.45, gap / full));
        const k = look.reach * word * (1 + (fit - 1) * fade);
        const full1 = full / word;
        const reach = full1 * k;
        // in a gust the tip may run about a tenth of a cap past the next stroke's edge, then it saturates
        const room = Math.max(1.15, (gap + 10) / Math.max(reach, 1e-3));
        const g = fade > 0 ? Math.min(FREE, room / fade) : FREE;
        over = Math.max(over, dir > 0 ? r + reach - wid : reach - l);
        return { l, r, k, g };
      });
    }
  }
  const wCap = (inkR - inkL) / 100; // ink width in cap heights
  const overCap = over / 100;
  // Fit: cap height about a third of the height, the word plus its needles (with room to gust) inside 84% of the width.
  let cap = Math.min(cssH * 0.309, (cssW * 0.84) / (wCap + overCap * (1 + 0.6 * look.wind)));
  cap = Math.min(cap, (cssH * 0.8 * 100) / (asc + desc));
  cap = Math.max(cap, 4);
  const s = cap / 100;
  const shift = cssW / 2 - ((inkL + inkR) / 2) * s - Math.max(0.04 * cap, 0.2 * over * s) * dir;
  return make(cap, shift, cssH / 2 + cap * 0.487);
}

/* Ink runs per sub-row of the wind band: [left, right] pairs in device px, sorted, found where coverage crosses one half. */
interface Band {
  top: number; // first device row of the band
  rows: number; // device rows in the band
  sub: number;
  texW: number; // texels per row, two runs per texel
  data: Float32Array;
}

function buildBand(L: Layout, top: number, rows: number, sub: number): Band {
  const dpr = L.dpr;
  const x0 = Math.max(0, Math.floor(L.inkL * dpr - 8));
  const x1 = Math.min(Math.ceil(L.cssW * dpr), Math.ceil(L.inkR * dpr + 8));
  const w = Math.max(1, x1 - x0);
  const total = rows * sub;
  const lists: number[][] = new Array(total);
  let maxRuns = 1;
  const chunk = Math.max(1, Math.min(total, Math.floor(4_000_000 / w)));
  const cv = document.createElement("canvas");
  cv.width = w;
  cv.height = chunk;
  const g = cv.getContext("2d", { willReadFrequently: true });
  if (!g) throw new Error("2d");
  for (let start = 0; start < total; start += chunk) {
    const h = Math.min(chunk, total - start);
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, w, chunk);
    g.setTransform(dpr, 0, 0, dpr * sub, -x0, -(top * sub + start));
    g.fillStyle = "#ffffff"; // ls:keep
    drawWord(g, L);
    const d = g.getImageData(0, 0, w, h).data;
    for (let r = 0; r < h; r++) {
      const runs: number[] = [];
      let prev = 0;
      let open = -1;
      const o = r * w * 4 + 3;
      for (let x = 0; x <= w; x++) {
        const c = x < w ? d[o + x * 4] / 255 : 0;
        if (prev < 0.5 && c >= 0.5) open = x - 0.5 + (0.5 - prev) / (c - prev);
        else if (prev >= 0.5 && c < 0.5) {
          runs.push(open + x0, x - 0.5 + (prev - 0.5) / (prev - c) + x0);
          open = -1;
        }
        prev = c;
      }
      lists[start + r] = runs;
      if (runs.length / 2 > maxRuns) maxRuns = runs.length / 2;
    }
  }
  const texW = Math.ceil((maxRuns + 1) / 2);
  const data = new Float32Array(texW * total * 4);
  for (let k = 0; k < total; k++) {
    const runs = lists[k];
    const base = k * texW * 4;
    for (let i = 0; i < texW * 2; i++) {
      if (i * 2 < runs.length) {
        data[base + i * 2] = runs[i * 2];
        data[base + i * 2 + 1] = runs[i * 2 + 1];
      } else {
        data[base + i * 2] = 1e6; // sentinel: empty
        data[base + i * 2 + 1] = -1e6;
      }
    }
  }
  return { top, rows, sub, texW, data };
}

/* The wind field arrives as a small lookup texture across the canvas width, refreshed every frame on the CPU:
   r = drag multiplier (gusts times the resting lens profile), g = signed needle multiplier, b = band reach multiplier, a = seam glow boost. */
const GLSL = `#version 300 es
precision highp float;
precision highp int;
uniform vec2 uRes;
uniform sampler2D uMask;
uniform highp sampler2D uRuns;
uniform sampler2D uWind;
uniform int uTexW;
uniform float uBandTop;
uniform float uBandBot;
uniform float uSub;
uniform float uY0;
uniform float uLam;
uniform float uR;
uniform float uMaxD;
uniform float uMaxB;
uniform float uS;
uniform float uE;
uniform float uK;
uniform float uK1;
uniform float uHW;
uniform float uHC;
uniform float uHaloR;
uniform float uHalo;
uniform float uPh;
uniform vec3 uInk;
uniform vec3 uAccent;
uniform vec3 uGlow;
uniform vec3 uBg0;
uniform vec3 uBg1;
uniform float uBgA;
uniform vec2 uWord;
out vec4 outColor;

float hash(vec2 p) {
  p = fract(p * vec2(443.897, 441.423));
  p += dot(p, p.yx + 19.19);
  return fract((p.x + p.y) * p.x);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i), b = hash(i + vec2(1.0, 0.0)), c = hash(i + vec2(0.0, 1.0)), d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
vec4 windAt(float x) {
  return texture(uWind, vec2(x / uRes.x, 0.5));
}
// Vertical falloff of the drag, a distance a from the seam: the sharp exponential cusp that draws the needle,
// windowed so it reaches exactly zero with zero slope at the band reach uR. One smooth field, no seam at the band edge.
float bendAt(float a, float lam) {
  float t = min(a / uR, 1.0);
  float w = 1.0 - t * t * t * t;
  return exp(-a / lam) * w * w;
}
// Overlap of the dragged run [l, r] with the box [x0, x1], a distance ady from the seam. Each edge moves by the wind at
// its own resting position, so the displacement is a continuous field of (x, y) that does not depend on which pixel
// is shading or on how the strokes split into runs on that row.
float runOverlap(float l, float r, float ady, float x0, float x1) {
  vec4 wl = windAt(l);
  vec4 wr = windAt(r);
  float fl = bendAt(ady, uLam * wl.b);
  float fr = bendAt(ady, uLam * wr.b);
  float lo = l + wl.r * uS * fl + min(wl.g * uE * fl, 0.0);
  float hi = r + wr.r * uS * fr + max(wr.g * uE * fr, 0.0);
  return max(min(hi, x1) - max(lo, x0), 0.0);
}

void main() {
  float px = gl_FragCoord.x;
  float py = uRes.y - gl_FragCoord.y;
  vec2 uv = vec2(px, py) / uRes;

  // sky: a diagonal fade with faint wind-combed wisps that drift round the loop
  float t = -0.055 + 0.469 * uv.x + 0.76 * uv.y;
  vec2 q = vec2(uv.x * 0.92 - uv.y * 0.39, uv.x * 0.39 + uv.y * 0.92);
  float ang = uPh * 6.2831853;
  vec2 drift = vec2(cos(ang), sin(ang)) * 0.35;
  float wisp = vnoise(vec2(q.x * 2.2, q.y * 9.0) + drift) * 0.6 + vnoise(vec2(q.x * 4.4, q.y * 19.0) - drift * 1.7) * 0.4;
  t += (wisp - 0.5) * 0.09;
  vec3 bg = mix(uBg0, uBg1, clamp(t, 0.0, 1.0));

  vec4 w0 = windAt(px);
  float row = floor(py);
  float dyc = py - uY0;
  float cov;
  if (row < uBandTop || row >= uBandBot) {
    cov = texelFetch(uMask, ivec2(int(px), int(row)), 0).a;
  } else {
    // Sub-rows per pixel from the steepest bend anywhere on this row (uMaxD, uMaxB come from the whole wind field),
    // so neighbouring columns always share one sampling pattern and edges stay even.
    float fmax = bendAt(max(abs(dyc) - 0.5, 0.0), uLam * uMaxB);
    float slope = 1.3 * uMaxD * fmax / uLam;
    int n = slope > 2.5 ? 8 : (slope > 0.9 ? 4 : (slope > 0.3 ? 2 : 1));
    int stp = 8 / n;
    int kb = int((row - uBandTop) * uSub);
    float acc = 0.0;
    for (int j = 0; j < 8; j++) {
      if (j >= n) break;
      int k = kb + j * stp + stp / 2;
      float ys = uBandTop + (float(k) + 0.5) / uSub;
      float ady = abs(ys - uY0);
      float c = 0.0;
      for (int i = 0; i < 64; i++) {
        if (i >= uTexW) break;
        vec4 r = texelFetch(uRuns, ivec2(i, k), 0);
        if (r.x > r.y) break;
        c += min(runOverlap(r.x, r.y, ady, px - 0.5, px + 0.5), 1.0);
        if (r.z > r.w) break;
        c += min(runOverlap(r.z, r.w, ady, px - 0.5, px + 0.5), 1.0);
      }
      acc += min(c, 1.0);
    }
    cov = acc / float(n);
    // feather into the plain glyphs over the outermost rows of the band
    float edge = min(row - uBandTop, uBandBot - 1.0 - row);
    if (edge < 4.0) {
      float m = texelFetch(uMask, ivec2(int(px), int(row)), 0).a;
      cov = mix(m, cov, (edge + 0.5) / 4.5);
    }
  }

  // ink: deep navy far from the band, warming to the accent toward it, light at the seam
  float ady = abs(dyc);
  vec3 ink = mix(uInk, uAccent, 0.4 * exp(-ady / uK1) + 0.6 * exp(-ady / uK));
  float hz = (dyc - uHC) / uHW;
  float hs = dyc / (uHW * 3.0);
  float hl = exp(-hz * hz);
  ink = mix(ink, uGlow, hl + 0.25 * exp(-hs * hs) * (1.0 - hl));
  // a thin veil of sky over the first strokes, as if the light came from the left
  float xw = max(px - uWord.x, 0.0) / max(uWord.y, 1.0);
  ink = mix(ink, bg, 0.115 * smoothstep(0.22, 0.06, xw) * (0.25 + 0.75 * exp(-ady / uK * 0.72)));
  vec3 col = mix(bg, ink, cov);
  float alpha = mix(uBgA, 1.0, cov);

  // a thin bloom along the seam, only where the dragged strokes meet
  if (ady < uHaloR * 1.5 && uHalo > 0.0) {
    int ks = int(clamp((uY0 - uBandTop) * uSub, 0.0, (uBandBot - uBandTop) * uSub - 1.0));
    float rr = uHaloR;
    float c = 0.0;
    for (int i = 0; i < 64; i++) {
      if (i >= uTexW) break;
      vec4 r = texelFetch(uRuns, ivec2(i, ks), 0);
      if (r.x > r.y) break;
      c += runOverlap(r.x, r.y, 0.0, px - rr, px + rr);
      if (r.z > r.w) break;
      c += runOverlap(r.z, r.w, 0.0, px - rr, px + rr);
    }
    float h = min(c / (2.0 * rr), 1.0) * exp(-ady / (uHaloR * 0.1)) * uHalo * (1.0 + 0.4 * w0.a);
    h = clamp(h * (1.0 - cov), 0.0, 1.0);
    col = mix(col, uGlow, h);
    alpha = max(alpha, h);
  }

  // static dither so the long sky fade never bands
  col += (hash(vec2(px, py) * 0.37) - 0.5) / 255.0;
  outColor = vec4(col * alpha, alpha);
}`;

const VERT = `#version 300 es
in vec2 p;
void main() { gl_Position = vec4(p, 0.0, 1.0); }`;

interface Uniforms {
  [k: string]: WebGLUniformLocation | null;
}

interface GLState {
  gl: WebGL2RenderingContext;
  prog: WebGLProgram;
  u: Uniforms;
  mask: WebGLTexture;
  runs: WebGLTexture;
  wind: WebGLTexture;
  buf: WebGLBuffer;
  vao: WebGLVertexArrayObject;
}

function makeGL(canvas: HTMLCanvasElement): GLState | null {
  const gl = canvas.getContext("webgl2", { premultipliedAlpha: true, antialias: false, alpha: true });
  if (!gl) return null;
  const sh = (type: number, src: string) => {
    const s = gl.createShader(type);
    if (!s) return null;
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      console.warn("WindType shader", gl.getShaderInfoLog(s));
      return null;
    }
    return s;
  };
  const vs = sh(gl.VERTEX_SHADER, VERT);
  const fs = sh(gl.FRAGMENT_SHADER, GLSL);
  const prog = gl.createProgram();
  if (!vs || !fs || !prog) return null;
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return null;
  const names = [
    "uRes", "uMask", "uRuns", "uWind", "uTexW", "uBandTop", "uBandBot", "uSub", "uY0", "uLam", "uR", "uMaxD", "uMaxB", "uS", "uE", "uK", "uK1", "uHW",
    "uHC", "uHaloR", "uHalo", "uPh", "uInk", "uAccent", "uGlow", "uBg0", "uBg1", "uBgA", "uWord",
  ];
  const u: Uniforms = {};
  for (const n of names) u[n] = gl.getUniformLocation(prog, n);
  const buf = gl.createBuffer();
  const vao = gl.createVertexArray();
  const mask = gl.createTexture();
  const runs = gl.createTexture();
  const wind = gl.createTexture();
  if (!buf || !vao || !mask || !runs || !wind) return null;
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog, "p");
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
  for (const t of [mask, runs, wind]) {
    const lin = t === wind ? gl.LINEAR : gl.NEAREST;
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, lin);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, lin);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  }
  return { gl, prog, u, mask, runs, wind, buf, vao };
}

interface Frame {
  ph: number; // loop phase 0..1
  wind: number; // gust strength, 0 for the resting frame
  ptrX: number; // css px
  ptrAmp: number; // signed
}

interface Scene {
  L: Layout;
  band: Band;
  y0: number; // resting seam, device px
  drift: number; // seam drift amplitude, device px
  lam: number;
  win: number; // distance from the seam at which the bend has fallen to exactly zero, device px
  S: number;
  E: number;
  dir: number;
  ink: RGB;
  accent: RGB;
  glowC: RGB;
  bg0: RGB;
  bg1: RGB;
  bgA: number;
}

function seamAt(sc: Scene, ph: number, moving: boolean) {
  if (!moving) return sc.y0;
  const a = ph * Math.PI * 2;
  return sc.y0 + sc.drift * (Math.sin(a) + 0.35 * Math.sin(2 * a + 1.3) - 0.35 * Math.sin(1.3));
}

/* Gust shape: a quick swell and a long settle, periodic over the loop and exactly zero at its start. */
function bump(p: number) {
  p -= Math.floor(p);
  const v = (1 - Math.exp(-p / 0.045)) * Math.exp(-p / 0.16);
  return (v - p * 0.00193) / 0.511;
}

const LUT = 512;
/* The resting drag grows toward both ends of the word, more at the upwind end, as measured on the reference. */
function lensAt(xn: number, dir: number) {
  const xd = dir > 0 ? xn : 1 - xn;
  const q = (2 * xd - 1) * (2 * xd - 1);
  return 1 + (xd < 0.5 ? 1.55 : 0.9) * q;
}

/* Wind across the canvas width for one frame: drag, signed needle, band reach and glow multipliers. */
function windField(sc: Scene, fr: Frame, W: number, out: Float32Array) {
  const dpr = sc.L.dpr;
  const x0 = sc.L.inkL * dpr;
  const ww = Math.max(1, (sc.L.inkR - sc.L.inkL) * dpr);
  const sig = 1.4 * sc.L.cap * dpr;
  const px = fr.ptrX * dpr;
  for (let i = 0; i < LUT; i++) {
    const x = ((i + 0.5) * W) / LUT;
    const xn = Math.min(1, Math.max(0, (x - x0) / ww));
    const xd = sc.dir > 0 ? xn : 1 - xn;
    const G = fr.wind > 0 ? bump(fr.ph - 0.1 - 0.07 * xd) + 0.62 * bump(fr.ph - 0.56 - 0.07 * xd) : 0;
    const flutter = G * 0.1 * Math.sin(Math.PI * 2 * 11 * fr.ph - xd * 9);
    const pd = (x - px) / sig;
    const a = sc.dir * (1 + fr.wind * (G + flutter)) + fr.ptrAmp * Math.exp(-pd * pd);
    const aa = Math.abs(a);
    const lens = lensAt(xn, sc.dir);
    const u = (x / dpr - sc.L.inkL) * (100 / sc.L.cap);
    const kk = needleAt(sc.L.needles, u, "k", sc.L.rest);
    const gm = needleAt(sc.L.needles, u, "g", FREE);
    // gusts mostly lengthen the needles; the drag itself grows by half as much
    const drag = aa <= 1 ? aa : 1 + 0.5 * (aa - 1);
    const need = aa <= 1 ? Math.pow(aa, 1.5) : 1 + 1.3 * (aa - 1);
    // growth of this needle's reach over its resting reach, softly saturated at gm (smooth, slope 1 at rest)
    const grow = (sc.S * lens * drag + sc.E * need) / (sc.S * lens + sc.E);
    const sat = grow <= 1 || gm >= FREE ? 1 : (1 + (gm - 1) * Math.tanh((grow - 1) / (gm - 1))) / grow;
    out[i * 4] = Math.sign(a) * drag * lens * kk * sat;
    out[i * 4 + 1] = Math.sign(a) * need * kk * sat;
    out[i * 4 + 2] = 1 + 0.22 * Math.max(aa - 1, 0);
    out[i * 4 + 3] = fr.wind * G;
  }
}

function inkTones(sc: Scene) {
  const C = sc.L.cap * sc.L.dpr;
  return { k: 0.18 * C, k1: 0.0225 * C, hw: Math.max(0.9, 0.0071 * C), hc: 0.0014 * C, haloR: Math.max(3, 0.04 * C) };
}

const windBuf = new Float32Array(LUT * 4);

function drawGL(st: GLState, sc: Scene, fr: Frame, moving: boolean) {
  const { gl, u } = st;
  const { band } = sc;
  const W = gl.drawingBufferWidth;
  windField(sc, fr, W, windBuf);
  gl.viewport(0, 0, W, gl.drawingBufferHeight);
  gl.useProgram(st.prog);
  gl.bindVertexArray(st.vao);
  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, st.mask);
  gl.uniform1i(u.uMask, 0);
  gl.activeTexture(gl.TEXTURE1);
  gl.bindTexture(gl.TEXTURE_2D, st.runs);
  gl.uniform1i(u.uRuns, 1);
  gl.activeTexture(gl.TEXTURE2);
  gl.bindTexture(gl.TEXTURE_2D, st.wind);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, LUT, 1, 0, gl.RGBA, gl.FLOAT, windBuf);
  gl.uniform1i(u.uWind, 2);
  gl.uniform2f(u.uRes, W, gl.drawingBufferHeight);
  gl.uniform1i(u.uTexW, band.texW);
  gl.uniform1f(u.uBandTop, band.top);
  gl.uniform1f(u.uBandBot, band.top + band.rows);
  gl.uniform1f(u.uSub, band.sub);
  gl.uniform1f(u.uY0, seamAt(sc, fr.ph, moving));
  gl.uniform1f(u.uLam, sc.lam);
  gl.uniform1f(u.uR, sc.win);
  let maxD = 0;
  let maxB = 1;
  for (let i = 0; i < LUT; i++) {
    maxD = Math.max(maxD, Math.abs(windBuf[i * 4]) * sc.S + Math.abs(windBuf[i * 4 + 1]) * sc.E);
    maxB = Math.max(maxB, windBuf[i * 4 + 2]);
  }
  gl.uniform1f(u.uMaxD, maxD);
  gl.uniform1f(u.uMaxB, maxB);
  gl.uniform1f(u.uS, sc.S);
  gl.uniform1f(u.uE, sc.E);
  const tn = inkTones(sc);
  gl.uniform1f(u.uK, tn.k);
  gl.uniform1f(u.uK1, tn.k1);
  gl.uniform1f(u.uHW, tn.hw);
  gl.uniform1f(u.uHC, tn.hc);
  gl.uniform1f(u.uHaloR, tn.haloR);
  gl.uniform1f(u.uHalo, 0.7);
  gl.uniform1f(u.uPh, fr.ph);
  gl.uniform3f(u.uInk, sc.ink[0], sc.ink[1], sc.ink[2]);
  gl.uniform3f(u.uAccent, sc.accent[0], sc.accent[1], sc.accent[2]);
  gl.uniform3f(u.uGlow, sc.glowC[0], sc.glowC[1], sc.glowC[2]);
  gl.uniform3f(u.uBg0, sc.bg0[0], sc.bg0[1], sc.bg0[2]);
  gl.uniform3f(u.uBg1, sc.bg1[0], sc.bg1[1], sc.bg1[2]);
  gl.uniform1f(u.uBgA, sc.bgA);
  gl.uniform2f(u.uWord, sc.L.inkL * sc.L.dpr, (sc.L.inkR - sc.L.inkL) * sc.L.dpr);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}

/* CPU fallback without WebGL 2: the resting frame, drawn once per layout. */
function drawCPU(canvas: HTMLCanvasElement, sc: Scene) {
  const g = canvas.getContext("2d");
  if (!g) return;
  const { L, band } = sc;
  const W = canvas.width;
  const H = canvas.height;
  const dpr = L.dpr;
  g.setTransform(1, 0, 0, 1, 0, 0);
  g.clearRect(0, 0, W, H);
  const mix = (a: RGB, b: RGB, t: number): RGB => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
  const css = (c: RGB, a = 1) => `rgba(${Math.round(c[0] * 255)},${Math.round(c[1] * 255)},${Math.round(c[2] * 255)},${a})`;
  if (sc.bgA > 0) {
    const gr = g.createLinearGradient(-0.055 * W, -0.055 * H, W * 0.469 * 1.6, H * 0.76 * 1.6);
    gr.addColorStop(0, css(sc.bg0, sc.bgA));
    gr.addColorStop(1, css(sc.bg1, sc.bgA));
    g.fillStyle = gr;
    g.fillRect(0, 0, W, H);
  }
  const tn = inkTones(sc);
  const inkAt = (dy: number): RGB => {
    const ady = Math.abs(dy);
    const c = mix(sc.ink, sc.accent, 0.4 * Math.exp(-ady / tn.k1) + 0.6 * Math.exp(-ady / tn.k));
    const hz = (dy - tn.hc) / tn.hw;
    const hs = dy / (tn.hw * 3);
    const hl = Math.exp(-hz * hz);
    return mix(c, sc.glowC, hl + 0.25 * Math.exp(-hs * hs) * (1 - hl));
  };
  // plain glyphs outside the band, with the vertical ink fade
  g.save();
  g.beginPath();
  g.rect(0, 0, W, band.top);
  g.rect(0, band.top + band.rows, W, H - band.top - band.rows);
  g.clip();
  const lg = g.createLinearGradient(0, (L.baseline - L.cap * 1.3) * dpr, 0, (L.baseline + L.cap * 0.3) * dpr);
  for (let i = 0; i <= 12; i++) {
    const y = (L.baseline - L.cap * 1.3 + (L.cap * 1.6 * i) / 12) * dpr;
    lg.addColorStop(i / 12, css(inkAt(y - sc.y0)));
  }
  g.fillStyle = lg;
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  drawWord(g, L);
  g.restore();
  // band rows from the run table, dragged by the resting wind
  const field = new Float32Array(LUT * 4);
  windField(sc, { ph: 0, wind: 0, ptrX: 0, ptrAmp: 0 }, W, field);
  // linear lookup, as the GPU texture filter does
  const windAt = (x: number) => {
    const u = Math.min(LUT - 1, Math.max(0, (x / W) * LUT - 0.5));
    const i = Math.min(LUT - 2, Math.floor(u));
    const t = u - i;
    const at = (c: number) => field[i * 4 + c] + (field[(i + 1) * 4 + c] - field[i * 4 + c]) * t;
    return [at(0), at(1), at(2)];
  };
  const bendAt = (a: number, lam: number) => {
    const t = Math.min(a / sc.win, 1);
    const w = 1 - t * t * t * t;
    return Math.exp(-a / lam) * w * w;
  };
  const img = g.getImageData(0, band.top, W, band.rows);
  const d = img.data;
  for (let r = 0; r < band.rows; r++) {
    const cov = new Float32Array(W);
    for (let j = 0; j < band.sub; j++) {
      const k = r * band.sub + j;
      const ys = band.top + (k + 0.5) / band.sub;
      const ady = Math.abs(ys - sc.y0);
      const base = k * band.texW * 4;
      for (let i = 0; i < band.texW * 2; i++) {
        const l0 = band.data[base + i * 2];
        const r0 = band.data[base + i * 2 + 1];
        if (l0 > r0) break;
        const wl = windAt(l0);
        const wr = windAt(r0);
        const fl = bendAt(ady, sc.lam * wl[2]);
        const fr = bendAt(ady, sc.lam * wr[2]);
        const l = l0 + wl[0] * sc.S * fl + Math.min(wl[1] * sc.E * fl, 0);
        const rr = r0 + wr[0] * sc.S * fr + Math.max(wr[1] * sc.E * fr, 0);
        for (let x = Math.max(0, Math.floor(l)); x < Math.min(W, Math.ceil(rr)); x++) {
          cov[x] += Math.max(0, Math.min(rr, x + 1) - Math.max(l, x)) / band.sub;
        }
      }
    }
    const c = inkAt(band.top + r + 0.5 - sc.y0);
    for (let x = 0; x < W; x++) {
      const a = Math.min(1, cov[x]);
      if (a <= 0) continue;
      const o = (r * W + x) * 4;
      const ba = d[o + 3] / 255;
      const outA = a + ba * (1 - a);
      for (let ch = 0; ch < 3; ch++) d[o + ch] = (c[ch] * 255 * a + d[o + ch] * ba * (1 - a)) / Math.max(outA, 1e-6);
      d[o + 3] = outA * 255;
    }
  }
  g.putImageData(img, 0, band.top);
}

/**
 * A display word with its middle band dragged sideways by wind: the tops and bottoms of the
 * letters stay crisp while every stroke crossing the band bends and tapers into a fine needle
 * that meets its twin along a lit seam. Gusts lengthen, flutter and sweep the needles, the band
 * drifts, and the pointer blows its own gust.
 */
export function WindType({
  text = "LOUIS",
  color = "#02050b",
  accent = "#0a94f5",
  glow = "#a6f2ff",
  background = "#cfe6f5",
  haze = "#f9f9f9",
  font,
  weight = 500,
  tracking = 0,
  bandPosition = 0.388,
  bandHeight = 0.128,
  streakLength = 0.22,
  reach = 1,
  windStrength = 1,
  speed = 1,
  direction = "right",
  interactive = true,
  paused = false,
  time,
  className,
  style,
}: WindTypeProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const [size, setSize] = React.useState<{ w: number; h: number; dpr: number } | null>(null);
  const [reduced, setReduced] = React.useState(false);
  const [glFailed, setGlFailed] = React.useState(false);
  const [glGen, setGlGen] = React.useState(0);
  const glRef = React.useRef<GLState | null>(null);
  const sceneRef = React.useRef<Scene | null>(null);
  const ptrRef = React.useRef({ x: 0, amp: 0, lastX: 0, lastT: 0, inside: false });
  const clockRef = React.useRef({ t: 0, last: 0 });
  const drawRef = React.useRef<() => void>(() => {});
  const dir = direction === "left" ? -1 : 1;

  React.useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const on = () => setReduced(mq.matches);
    on();
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const measure = () => {
      const r = el.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = Math.max(1, Math.round(r.width));
      const h = Math.max(1, Math.round(r.height));
      setSize((s) => (s && s.w === w && s.h === h && s.dpr === dpr ? s : { w, h, dpr }));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    window.addEventListener("resize", measure);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, []);

  // Build layout, glyph mask and band run table whenever the look or size changes.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !size) return;
    let cancelled = false;
    const build = () => {
      if (cancelled) return;
      const W = Math.round(size.w * size.dpr);
      const H = Math.round(size.h * size.dpr);
      if (canvas.width !== W) canvas.width = W;
      if (canvas.height !== H) canvas.height = H;
      const mc = document.createElement("canvas");
      mc.width = W;
      mc.height = H;
      const mg = mc.getContext("2d", { willReadFrequently: true });
      if (!mg) return;
      const L = layoutWord(mg, text, font, weight, tracking, { s: streakLength * (1 - NEED), e: streakLength * NEED, band: bandPosition, wind: Math.max(0, windStrength), reach: Math.max(0, reach) }, dir, size.w, size.h, size.dpr);
      mg.setTransform(size.dpr, 0, 0, size.dpr, 0, 0);
      mg.fillStyle = "#ffffff"; // ls:keep
      drawWord(mg, L);
      const C = L.cap * size.dpr;
      const lam = (bandHeight / 3.8) * C;
      const S = streakLength * (1 - NEED) * C;
      const E = streakLength * NEED * C;
      const y0 = (L.baseline - bandPosition * L.cap) * size.dpr;
      const drift = 0.022 * C;
      const maxA = 1 + Math.max(0, windStrength) * 1.25 + 1.6;
      const span = Math.min(0.75 * C, 7.5 * lam * (1 + 0.22 * (maxA - 1)) + drift * 1.4 + 2);
      let top = Math.max(0, Math.floor(y0 - span));
      let bot = Math.min(H, Math.ceil(y0 + span));
      let sub = SUB;
      const st = glRef.current;
      const maxTex = st ? (st.gl.getParameter(st.gl.MAX_TEXTURE_SIZE) as number) : 8192;
      while ((bot - top) * sub > maxTex && sub > 2) sub /= 2;
      if ((bot - top) * sub > maxTex) {
        const mid = (top + bot) / 2;
        top = Math.floor(mid - maxTex / sub / 2);
        bot = top + Math.floor(maxTex / sub);
      }
      if (bot <= top) bot = top + 1;
      const band = buildBand(L, top, bot - top, sub);
      const bgP = parseColor(background, [0.81, 0.9, 0.96]);
      const sc: Scene = {
        L,
        band,
        y0,
        drift,
        lam,
        // the bend window closes a little inside the band, wherever the seam drifts, so the band edge never moves
        win: Math.max(2 * lam, Math.min(y0 - top, bot - y0) - drift * 1.4 - 1),
        S,
        E,
        dir,
        ink: parseColor(color, [0, 0.02, 0.04]).rgb,
        accent: parseColor(accent, [0.02, 0.43, 0.7]).rgb,
        glowC: parseColor(glow, [0.75, 0.98, 1]).rgb,
        bg0: bgP.rgb,
        bg1: parseColor(haze, [0.98, 0.98, 0.98]).rgb,
        bgA: bgP.a,
      };
      sceneRef.current = sc;
      if (st) {
        const { gl } = st;
        gl.bindTexture(gl.TEXTURE_2D, st.mask);
        gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, mc);
        gl.bindTexture(gl.TEXTURE_2D, st.runs);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA32F, band.texW, band.rows * band.sub, 0, gl.RGBA, gl.FLOAT, band.data);
      } else {
        drawCPU(canvas, sc);
      }
      drawRef.current();
    };
    const fonts = (document as Document & { fonts?: FontFaceSet }).fonts;
    build();
    if (fonts && fonts.status !== "loaded") fonts.ready.then(build).catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [size, text, font, weight, tracking, bandPosition, bandHeight, streakLength, reach, windStrength, dir, color, accent, glow, background, haze, glFailed, glGen]);

  // WebGL setup once per canvas.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const st = makeGL(canvas);
    if (!st) {
      setGlFailed(true);
      return;
    }
    glRef.current = st;
    let cur: GLState | null = st;
    const onLost = (e: Event) => {
      e.preventDefault();
      glRef.current = null;
      cur = null;
    };
    const onRestored = () => {
      cur = makeGL(canvas);
      glRef.current = cur;
      setGlGen((g) => g + 1);
    };
    canvas.addEventListener("webglcontextlost", onLost);
    canvas.addEventListener("webglcontextrestored", onRestored);
    return () => {
      canvas.removeEventListener("webglcontextlost", onLost);
      canvas.removeEventListener("webglcontextrestored", onRestored);
      if (!cur) return;
      const st = cur;
      const { gl } = st;
      gl.deleteTexture(st.mask);
      gl.deleteTexture(st.runs);
      gl.deleteTexture(st.wind);
      gl.deleteBuffer(st.buf);
      gl.deleteVertexArray(st.vao);
      gl.deleteProgram(st.prog);
      glRef.current = null;
    };
  }, []);

  // Render loop.
  React.useEffect(() => {
    const ptr = ptrRef.current;
    const clock = clockRef.current;
    const period = LOOP / Math.max(0.05, speed);
    const render = () => {
      const st = glRef.current;
      const sc = sceneRef.current;
      if (!st || !sc) return;
      const tt = time !== undefined ? time : clock.t;
      const ph = (((tt / period) % 1) + 1) % 1;
      const fr: Frame = reduced
        ? { ph: 0, wind: 0, ptrX: 0, ptrAmp: 0 }
        : { ph, wind: Math.max(0, windStrength), ptrX: ptr.x, ptrAmp: interactive ? ptr.amp : 0 };
      drawGL(st, sc, fr, !reduced);
    };
    drawRef.current = render;
    render();
    if (reduced || time !== undefined) return;
    let raf = 0;
    let visible = true;
    let onScreen = true;
    const loop = (now: number) => {
      raf = 0;
      const dt = clock.last ? Math.min(0.1, (now - clock.last) / 1000) : 0;
      clock.last = now;
      if (!paused) clock.t += dt;
      ptr.amp *= Math.exp(-dt / 0.65);
      if (Math.abs(ptr.amp) < 1e-3) ptr.amp = 0;
      render();
      if (visible && onScreen && (!paused || ptr.amp !== 0)) raf = requestAnimationFrame(loop);
    };
    const start = () => {
      if (!raf && visible && onScreen) {
        clock.last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };
    const onVis = () => {
      visible = document.visibilityState !== "hidden";
      if (visible) start();
      else stop();
    };
    const io = new IntersectionObserver((ents) => {
      onScreen = ents.some((e) => e.isIntersecting);
      if (onScreen) start();
      else stop();
    });
    if (rootRef.current) io.observe(rootRef.current);
    document.addEventListener("visibilitychange", onVis);
    const kick = () => start();
    const el = rootRef.current;
    el?.addEventListener("windtype:kick", kick);
    start();
    return () => {
      stop();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      el?.removeEventListener("windtype:kick", kick);
    };
  }, [reduced, time, paused, speed, windStrength, interactive]);

  const onPointerMove = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (!interactive || reduced) return;
      const r = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - r.left;
      const now = performance.now();
      const p = ptrRef.current;
      if (p.inside && p.lastT) {
        const dt = Math.max(8, now - p.lastT) / 1000;
        const vx = (x - p.lastX) / dt;
        const target = Math.max(-2.4, Math.min(2.4, vx / 700));
        p.amp += (target - p.amp) * 0.3;
      }
      p.x = x;
      p.lastX = x;
      p.lastT = now;
      p.inside = true;
      e.currentTarget.dispatchEvent(new Event("windtype:kick"));
    },
    [interactive, reduced],
  );
  const onPointerLeave = React.useCallback(() => {
    ptrRef.current.inside = false;
    ptrRef.current.lastT = 0;
  }, []);

  return (
    <div
      ref={rootRef}
      className={className}
      role="img"
      aria-label={text}
      onPointerMove={onPointerMove}
      onPointerLeave={onPointerLeave}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        minHeight: 360,
        overflow: "hidden",
        touchAction: "pan-y",
        ...style,
      }}
    >
      <canvas ref={canvasRef} aria-hidden="true" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }} />
    </div>
  );
}

export default WindType;

